package com.gameaggregator.webhookservice.application;import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;class WebhookSecretCipherTest{@Test void encryptsAndDecryptsWithoutStoringPlaintext(){var c=new WebhookSecretCipher("01234567890123456789012345678901");String raw="webhook-secret";String encrypted=c.encrypt(raw);assertThat(encrypted).doesNotContain(raw);assertThat(c.decrypt(encrypted)).isEqualTo(raw);assertThat(c.encrypt(raw)).isNotEqualTo(encrypted);}}